+//! time (added … done), then completed | incomplete | failed.
+
+use serde_json::{json, Value};
+
+use super::{
+    call_item, custom_input, failed_error, message_item, new_id, now_secs, output_text_part,
+    reasoning_item, response_object, usage_from_chat, EchoContext, Finish,
+};
+use crate::protocol::sse::{data_payload, write_event, LineBuffer, SseTransducer};
+
+enum Open {
+    Reasoning {
+        id: String,
+        index: usize,
+        text: String,
+    },
+    Message {
+        id: String,
+        index: usize,
+        text: String,
+    },
+    Function {
+        id: String,
+        index: usize,
+        tool_index: u64,
+        call_id: String,
+        name: String,
+        args: String,
+    },
+}
+
+pub struct ResponsesStream {
+    echo: EchoContext,
+    id: String,
+    created_at: u64,
+    seq: u64,
+    lines: LineBuffer,
+    started: bool,
+    terminal: bool,
+    open: Option<Open>,
+    output: Vec<Value>,
+    finish_reason: Option<String>,
+    usage: Option<Value>,
