+impl ResponsesStream {
+    pub fn new(echo: EchoContext) -> Self {
+        Self {
+            echo,
+            id: new_id("resp"),
+            created_at: now_secs(),
+            seq: 0,
+            lines: LineBuffer::default(),
+            started: false,
+            terminal: false,
+            open: None,
+            output: Vec::new(),
+            finish_reason: None,
+            usage: None,
+        }
+    }
+
+    fn handle_line(&mut self, line: &[u8], out: &mut Vec<u8>) {
+        if self.terminal {
+            return;
+        }
