+                json!({"item_id": id, "output_index": index, "content_index": 0,
+                       "part": {"type": "reasoning_text", "text": ""}}),
+                out,
+            );
+            self.open = Some(Open::Reasoning {
+                id,
+                index,
+                text: String::new(),
+            });
+        }
+        let Some(Open::Reasoning { id, index, text }) = &mut self.open else {
+            unreachable!()
+        };
+        text.push_str(delta);
