+            "image_url" => part.clone(),
+            other => {
+                return Err(format!(
+                    "input[{i}]: content part type `{other}` is not supported"
+                ))
+            }
+        };
+        out.push(converted);
+    }
+    if let [single] = out.as_slice() {
+        if single["type"] == "text" {
+            return Ok(single["text"].clone());
+        }
+    }
