+            let message = err
+                .get("message")
+                .and_then(Value::as_str)
+                .unwrap_or("upstream error");
+            self.emit_failed(message, out);
+            return;
+        }
+        if let Some(u) = chunk.get("usage").filter(|u| u.is_object()) {
+            self.usage = Some(u.clone());
