+                    "role": "tool",
+                    "tool_call_id": call_id,
+                    "content": output,
+                }));
+            }
+            "reasoning" => {
+                // Reasoning belongs to the following assistant turn.
+                if pending.content.is_some() || !pending.tool_calls.is_empty() {
