+        text.split("\n\n")
+            .filter(|b| !b.is_empty())
+            .map(|block| {
+                let mut lines = block.lines();
+                let ev = lines.next().unwrap().strip_prefix("event: ").unwrap();
+                let data = lines.next().unwrap().strip_prefix("data: ").unwrap();
+                (ev.to_owned(), serde_json::from_str(data).unwrap())
+            })
+            .collect()
+    }
