+/// Request fields echoed on every Response object.
+#[derive(Debug, Clone)]
+pub struct EchoContext {
+    pub model: String,
+    pub fields: Map<String, Value>,
+    pub tools: ToolMap,
+}
+
+/// A namespaced or `custom` tool, keyed in [`ToolMap`] by its chat function name.
+#[derive(Debug, Clone)]
+pub struct ToolRef {
+    pub namespace: Option<String>,
+    pub name: String,
+    pub custom: bool,
+}
+
