+/// `content[].text`, else `summary[].text`.
+fn reasoning_text(obj: &Map<String, Value>) -> String {
+    let join = |key: &str| -> String {
+        obj.get(key)
+            .and_then(Value::as_array)
+            .map(|parts| {
+                parts
+                    .iter()
+                    .filter_map(|p| p.get("text").and_then(Value::as_str))
+                    .collect::<Vec<_>>()
+                    .join("\n")
+            })
+            .unwrap_or_default()
+    };
+    let content = join("content");
+    if content.is_empty() {
+        join("summary")
+    } else {
+        content
+    }
