+
+    fn tool_delta(&mut self, call: &Value, out: &mut Vec<u8>) {
+        let tool_index = call.get("index").and_then(Value::as_u64).unwrap_or(0);
+        let same =
+            matches!(&self.open, Some(Open::Function { tool_index: t, .. }) if *t == tool_index);
+        if !same {
+            self.close_open(Finish::Completed, out);
+            let id = new_id("fc");
+            let index = self.output.len();
+            let call_id = call
+                .get("id")
+                .and_then(Value::as_str)
+                .map(str::to_owned)
+                .unwrap_or_else(|| new_id("call"));
+            let name = call
+                .pointer("/function/name")
+                .and_then(Value::as_str)
+                .unwrap_or("")
+                .to_owned();
+            self.emit(
+                "response.output_item.added",
+                json!({"output_index": index,
+                       "item": call_item(&id, &call_id, &name, "", "in_progress", &self.echo.tools)}),
+                out,
+            );
+            self.open = Some(Open::Function {
+                id,
+                index,
+                tool_index,
+                call_id,
+                name,
+                args: String::new(),
+            });
+        }
+        let Some(Open::Function {
+            id,
+            index,
+            name,
+            args,
+            ..
